window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[241]={"id":"241","numero":241,"titre":"Goitre, nodule thyroïdien et cancers thyroïdiens","objectifs":[{"id":"241-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un goitre","contenu":"<p>Le <strong><span class=\"kw-def\">goitre</span></strong> est une <strong>augmentation du volume de la glande thyroïde</strong>, soit <span class=\"kw-clinique\">diffuse</span>, soit <span class=\"kw-clinique\">localisée</span> (goitre nodulaire).</p>\n\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> L'existence d'un goitre <span class=\"kw-alerte\">ne préjuge pas du fonctionnement thyroïdien</span> : il peut être euthyroïdien, hypo- ou hyperthyroïdien.</div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Définir le seuil — deux critères</h4>\n      <p>Le volume thyroïdien normal varie selon l'<span class=\"kw-def\">âge</span> et la <span class=\"kw-def\">surface corporelle</span>.</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Seuil de goitre</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Clinique</strong> (palpation)</td><td>La surface de chacun des lobes excède celle de la <strong>dernière phalange du pouce</strong> du patient.</td></tr>\n          <tr><td><strong>Échographique</strong></td><td>Volume thyroïdien <span class=\"kw-chiffre\">&gt; 16 mL</span> chez l'adolescent ; <span class=\"kw-chiffre\">&gt; 18 mL</span> chez la femme ; <span class=\"kw-chiffre\">&gt; 20 mL</span> chez l'homme.</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Classification OMS — 3 grades cliniques</h4>\n      <table >\n        <thead><tr><th>Grade</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Grade 0</strong></td><td>Thyroïde non palpable et non visible (situation normale).</td></tr>\n          <tr><td><strong>Grade 1</strong></td><td>Goitre <span class=\"kw-clinique\">palpable mais non visible</span>, cou en position normale (les nodules d'une thyroïde non hypertrophiée entrent dans cette catégorie).</td></tr>\n          <tr><td><strong>Grade 2</strong></td><td>Goitre <span class=\"kw-clinique\">nettement visible</span>, cou en position normale.</td></tr>\n        </tbody>\n      </table>\n\n      <p><strong>Épidémiologie :</strong> prévalence d'environ <span class=\"kw-chiffre\">10 %</span> de la population, augmentant avec l'âge ; prédominance féminine (<span class=\"kw-chiffre\">3 F / 1 H</span>).</p>","frequence":1},{"id":"241-2","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître l’indications des examens d’imagerie devant un goitre, un ou des nodules","contenu":"<p>Chaque examen d'imagerie thyroïdien a une indication propre. <span class=\"kw-imagerie\">Échographie</span> et <span class=\"kw-imagerie\">scintigraphie</span> ne s'opposent pas : la première est <strong>morphologique</strong>, la seconde <strong>fonctionnelle</strong>.</p>\n\n      <table >\n        <thead><tr><th>Examen</th><th>Indication</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-imagerie\">Échographie thyroïdienne</span></strong></td><td><strong>Systématique devant tout nodule</strong> (plus sensible que la palpation) ; utile devant un goitre irrégulier (recherche de nodules) ; hypoéchogénicité des thyroïdites. Classe le risque de malignité (<span class=\"kw-def\">EU-TIRADS 2017</span>).</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">Scintigraphie</span></strong> (I123 ou Tc99m)</td><td><strong>Indiquée uniquement si <span class=\"kw-def\">hyperthyroïdie</span></strong> (<span class=\"kw-bio\">TSH</span> basse) — et <span class=\"kw-alerte\">non systématique si suspicion de Basedow</span>. CI : <span class=\"kw-ci\">grossesse</span>, <span class=\"kw-ci\">allaitement</span>.</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">TDM cervico-thoracique</span></strong></td><td>Bilan d'un <span class=\"kw-clinique\">goitre plongeant</span> ; bilan d'extension d'un cancer thyroïdien avancé (<span class=\"kw-clinique\">adénopathies</span> médiastinales, métastases pulmonaires).</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">TEP-TDM</span></strong></td><td>Bilan d'extension des cancers qui <strong>ne fixent pas/plus l'iode</strong> : <span class=\"kw-imagerie\">TEP-FDG</span> pour les cancers épithéliaux ; <span class=\"kw-imagerie\">TEP-F-DOPA</span> pour le cancer médullaire.</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">EU-TIRADS 2017 — risque échographique de malignité</h4>\n      <p>Score de <span class=\"kw-chiffre\">2 à 5</span>, risque de malignité de <span class=\"kw-chiffre\">0 à 87 %</span>. Facteurs échographiques de malignité : <span class=\"kw-alerte\">hypoéchogénicité</span>, <span class=\"kw-alerte\">microcalcifications</span>, <span class=\"kw-alerte\">caractère mal limité</span>, <span class=\"kw-alerte\">forme non ovalaire</span> (plus haute que large).</p>\n      <table >\n        <thead><tr><th>EU-TIRADS</th><th>Aspect</th></tr></thead>\n        <tbody>\n          <tr><td><strong>2</strong> — bénin</td><td>Kyste simple.</td></tr>\n          <tr><td><strong>3</strong> — bas risque</td><td>Nodule isoéchogène, bien limité.</td></tr>\n          <tr><td><strong>4</strong> — risque intermédiaire</td><td>Nodule modérément hypoéchogène, à marges régulières.</td></tr>\n          <tr><td><strong>5</strong> — haut risque</td><td>Nodule très hypoéchogène, plus haut que large, à marges irrégulières.</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\"><span class=\"kw-imagerie\">Scintigraphie</span> — interprétation</h4>\n      <table >\n        <thead><tr><th>Aspect</th><th>Orientation</th></tr></thead>\n        <tbody>\n          <tr><td>Hyperfixation <strong>globale</strong></td><td>Maladie de Basedow.</td></tr>\n          <tr><td>Hyperfixation <strong>localisée</strong></td><td><span class=\"kw-def\">Nodule chaud</span> / adénome toxique.</td></tr>\n          <tr><td>Hypofixation <strong>localisée</strong></td><td><span class=\"kw-def\">Nodule froid</span>.</td></tr>\n          <tr><td>Hypofixation <strong>globale</strong> (« <span class=\"kw-imagerie\">scintigraphie</span> blanche »)</td><td><span class=\"kw-def\">Thyroïdite</span> de De Quervain ; <span class=\"kw-def\">thyroïdite</span> du post-partum ; surcharge iodée type 2 ; thyrotoxicose factice.</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\"><strong>Drapeau rouge.</strong> Dans un cancer thyroïdien avancé, <span class=\"kw-alerte\">le scanner injecté doit être évité</span> (la surcharge en iode compromet une future <span class=\"kw-ttt\">IRAthérapie</span>) — sauf signes d'extension trachéale, œsophagienne ou à d'autres structures nobles.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 242 — <span class=\"kw-def\">Hyperthyroïdie</span> · 243 — <span class=\"kw-def\">Hypothyroïdie</span></em></p>","frequence":2,"liens":[{"href":"https://radiopaedia.org/articles/thyroid-malignancies","label":"Radiopaedia : Thyroid malignancies"},{"href":"https://radiopaedia.org/articles/papillary-thyroid-cancer","label":"Radiopaedia : Papillary thyroid cancer"},{"href":"https://radiopaedia.org/articles/follicular-thyroid-cancer","label":"Radiopaedia : Follicular thyroid cancer"},{"href":"https://radiopaedia.org/articles/octreotide-scintigraphy","label":"Radiopaedia : Octreotide scintigraphy"},{"href":"https://radiopaedia.org/articles/goiter-3","label":"Radiopaedia : Goiter 3"},{"href":"https://radiopaedia.org/articles/hashimoto-thyroiditis","label":"Radiopaedia : Hashimoto thyroiditis"},{"href":"https://radiopaedia.org/articles/european-thyroid-association-tirads","label":"Radiopaedia : European thyroid association tirads"},{"href":"https://radiopaedia.org/articles/thyroid-nodule","label":"Radiopaedia : Thyroid nodule"}]},{"id":"241-3","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les principaux facteurs favorisants de goitre, de nodules, de cancer","contenu":"<h4 style=\"margin:4px 0 6px;font-size:14px;\">Facteurs favorisants de goitre et de nodules</h4>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Facteurs</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Environnementaux</strong></td><td><strong><span class=\"kw-etio\">Carence iodée</span></strong> (même relative) = <strong>principal facteur goitrigène</strong> ; <span class=\"kw-etio\">tabac</span> (thiocyanates goitrigènes) ; polluants (solvants, benzène, perturbateurs endocriniens).</td></tr>\n          <tr><td><strong>Iatrogènes</strong></td><td><span class=\"kw-ttt\">Sels de lithium</span> et <span class=\"kw-ttt\">amiodarone</span> (inhibent la captation de l'iode) ; <span class=\"kw-alerte\">irradiation cervicale dans l'enfance</span>.</td></tr>\n          <tr><td><strong>Auto-immuns</strong></td><td>Maladie de Basedow ; <span class=\"kw-def\">thyroïdite</span> de Hashimoto ; <span class=\"kw-def\">thyroïdite</span> de De Quervain.</td></tr>\n          <tr><td><strong>Génétiques</strong></td><td>Prédisposition familiale (affection <span class=\"kw-def\">multigénique</span> — pas de dépistage) ; mutation du gène <span class=\"kw-def\">RET</span> (recherchée en pratique pour le cancer médullaire).</td></tr>\n          <tr><td><strong>Hormonaux</strong></td><td><span class=\"kw-etio\">Œstrogènes</span> (récepteurs sur les follicules) → apparition à la puberté, majoration pendant la grossesse et en cas de multiparité.</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Piège classique.</strong> Le <span class=\"kw-etio\">tabac</span> est goitrigène, mais il <span class=\"kw-alerte\">n'augmente PAS le risque de cancer thyroïdien</span>.</div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Facteurs favorisants de cancer thyroïdien</h4>\n      <ul>\n        <li><strong><span class=\"kw-alerte\">Irradiation cervicale dans l'enfance</span></strong> — seul facteur prouvé ; multiplie le risque par <span class=\"kw-chiffre\">7</span>.</li>\n        <li><strong>Âge <span class=\"kw-chiffre\">&lt; 16 ans</span></strong> au moment de la découverte du nodule.</li>\n        <li><strong><span class=\"kw-def\">NEM2</span></strong> et antécédents familiaux de cancer médullaire thyroïdien.</li>\n      </ul>\n      <p>La carence iodée, à l'échelle mondiale, est la principale cause de goitre ; ses formes sévères entraînent une <span class=\"kw-alerte\">hypothyroïdie profonde avec retentissement neurocognitif</span> (« crétinisme goitreux »). Apport iodé optimal : <span class=\"kw-chiffre\">100 à 150 µg/j</span> chez l'adulte, <span class=\"kw-chiffre\">200 à 250 µg/j</span> chez la femme enceinte.</p>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 242 — <span class=\"kw-def\">Hyperthyroïdie</span> · 243 — <span class=\"kw-def\">Hypothyroïdie</span></em></p>","frequence":3},{"id":"241-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les trois principaux diagnostics étiologiques de goitres","contenu":"<p>La démarche étiologique repose sur la <strong><span class=\"kw-bio\">TSH</span></strong> + l'<strong><span class=\"kw-imagerie\">échographie thyroïdienne</span></strong>. Trois diagnostics dominent, distingués d'abord par le statut fonctionnel.</p>\n\n      <table >\n        <thead><tr><th>Étiologie</th><th><span class=\"kw-bio\">TSH</span></th><th>Tableau caractéristique</th><th>Confirmation</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong><span class=\"kw-def\">Goitre simple</span></strong><br>(immense majorité)</td>\n            <td><span class=\"kw-bio\">Normale</span></td>\n            <td>Hypertrophie <span class=\"kw-clinique\">diffuse et homogène</span>, débutant à l'adolescence ; parenchyme souple ; <strong>normofonctionnel</strong>, non inflammatoire. Peut évoluer vers une forme multinodulaire.</td>\n            <td>AC anti-thyroïdiens <strong>négatifs</strong> ; <span class=\"kw-bio\">TSH</span> normale.</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Maladie de Basedow</span></strong></td>\n            <td><span class=\"kw-bio\">Basse</span></td>\n            <td><span class=\"kw-clinique\">Femme jeune</span> + <span class=\"kw-clinique\">goitre diffus</span> + <span class=\"kw-clinique\">hyperthyroïdie</span> ± signes extrathyroïdiens (orbitopathie).</td>\n            <td>Dosage des <strong><span class=\"kw-bio\">AC anti-récepteurs de la TSH</span></strong> (TRAK).</td>\n          </tr>\n          <tr>\n            <td><strong><span class=\"kw-def\">Thyroïdite de Hashimoto</span></strong></td>\n            <td><span class=\"kw-bio\">Élevée</span></td>\n            <td><span class=\"kw-def\">Thyroïdite</span> auto-immune ; femme de <span class=\"kw-chiffre\">40-60 ans</span> ; goitre <span class=\"kw-clinique\">irrégulier, ferme, pseudo-nodulaire</span> ; <strong>1ʳᵉ cause d'<span class=\"kw-def\">hypothyroïdie</span> en France</strong>.</td>\n            <td><strong><span class=\"kw-bio\">AC anti-TPO</span></strong> à titre élevé +++ (± anti-Tg).</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\" style=\"border-left:3px solid var(--warn);\"><strong>À distinguer — <span class=\"kw-def\">thyroïdite</span> de De Quervain.</strong> <span class=\"kw-def\">Thyroïdite</span> subaiguë d'origine <span class=\"kw-etio\">virale</span>, à début <strong>brutal</strong> : goitre <span class=\"kw-clinique\">douloureux</span>, ferme, dur ; syndrome pseudo-grippal fébrile ; <span class=\"kw-bio\">syndrome inflammatoire biologique</span> ; thyrotoxicose transitoire dans <span class=\"kw-chiffre\">50 %</span> des cas. Récupération en <span class=\"kw-chiffre\">2-3 mois</span>. AC le plus souvent négatifs.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 242 — <span class=\"kw-def\">Hyperthyroïdie</span> · 243 — <span class=\"kw-def\">Hypothyroïdie</span></em></p>","frequence":4},{"id":"241-5","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les trois principales complications évolutives d’un goitre","contenu":"<p>Un goitre — surtout multinodulaire et ancien — expose à trois complications évolutives principales.</p>\n\n      <table >\n        <thead><tr><th>Complication</th><th>Traduction</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1 · Compression</strong> (augmentation du volume)</td>\n            <td><span class=\"kw-clinique\">Troubles de la déglutition</span> ; <span class=\"kw-clinique\">dysphonie</span> ; <span class=\"kw-clinique\">gêne respiratoire</span> ; plus rarement <span class=\"kw-alerte\">compression veineuse</span> (syndrome cave supérieur). Le <span class=\"kw-def\">goitre plongeant</span> en est la forme étendue au médiastin.</td>\n          </tr>\n          <tr>\n            <td><strong>2 · <span class=\"kw-def\">Hyperthyroïdie</span></strong> par autonomisation</td>\n            <td>Autonomisation progressive des nodules hyperfonctionnels → <span class=\"kw-def\">goitre multinodulaire toxique</span>.</td>\n          </tr>\n          <tr>\n            <td><strong>3 · Cancérisation</strong></td>\n            <td>Un cancer est présent dans <span class=\"kw-chiffre\">4 à 5 %</span> des goitres plurinodulaires.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Devant un goitre plongeant : la <span class=\"kw-imagerie\">RXT</span> montre un <span class=\"kw-imagerie\">élargissement du médiastin supérieur antérieur</span> + déviation trachéale ; <span class=\"kw-imagerie\">TDM</span>/<span class=\"kw-imagerie\">IRM</span> confirment une lésion en continuité avec la thyroïde, souvent calcifiée.</div>","frequence":1},{"id":"241-6","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires à réaliser en première intention en présence d’un goitre","contenu":"<p>Le bilan de première intention d'un goitre se résume à deux examens : <strong><span class=\"kw-bio\">TSH</span></strong> + <strong><span class=\"kw-imagerie\">échographie thyroïdienne</span></strong>.</p>\n\n      <table >\n        <thead><tr><th>Temps</th><th>Examens</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1ʳᵉ intention</strong></td>\n            <td><strong>Dosage de la <span class=\"kw-bio\">TSH</span></strong> ; <strong><span class=\"kw-imagerie\">échographie</span></strong> (surtout si goitre irrégulier — recherche de nodules).</td>\n          </tr>\n          <tr>\n            <td><strong>2ⁿᵈᵉ intention</strong></td>\n            <td>Dosage <span class=\"kw-bio\">T4L</span> / <span class=\"kw-bio\">T3L</span> si la <span class=\"kw-bio\">TSH</span> est anormale (quantifie la dysfonction).</td>\n          </tr>\n          <tr>\n            <td><strong>Selon résultats</strong></td>\n            <td>\n              <strong><span class=\"kw-bio\">TSH</span> augmentée :</strong> <span class=\"kw-bio\">AC anti-TPO</span>, puis <span class=\"kw-bio\">AC anti-Tg</span> si anti-TPO négatifs → <span class=\"kw-def\">thyroïdite</span> de Hashimoto.<br>\n              <strong><span class=\"kw-bio\">TSH</span> basse, goitre diffus, sujet jeune :</strong> <span class=\"kw-bio\">AC anti-récepteurs de la TSH</span> → maladie de Basedow.<br>\n              <strong><span class=\"kw-bio\">TSH</span> basse, goitre plurinodulaire :</strong> <span class=\"kw-imagerie\">scintigraphie thyroïdienne</span> → goitre multinodulaire toxique.\n            </td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Le dosage de la <span class=\"kw-bio\">thyroglobuline</span> <span class=\"kw-alerte\">n'a pas sa place dans le bilan initial</span> d'un goitre — il est réservé à la <strong>surveillance des cancers thyroïdiens après thyroïdectomie totale</strong>, et doit toujours être couplé à la recherche d'AC anti-thyroglobuline.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 242 — <span class=\"kw-def\">Hyperthyroïdie</span> · 243 — <span class=\"kw-def\">Hypothyroïdie</span></em></p>","frequence":3},{"id":"241-7","rang":"A","rubrique":"Définition","titre":"Connaître la définition d’un nodule thyroïdien","contenu":"<p>Le <strong><span class=\"kw-def\">nodule thyroïdien</span></strong> est une <strong>hypertrophie localisée</strong> de la glande thyroïde, de forme généralement <span class=\"kw-clinique\">arrondie ou ovalaire</span>.</p>\n\n      <table >\n        <thead><tr><th>Caractéristique</th><th>Fréquence</th></tr></thead>\n        <tbody>\n          <tr><td>Nodule <strong>bénin</strong></td><td><span class=\"kw-chiffre\">95 %</span></td></tr>\n          <tr><td>Nodule <strong>cancéreux</strong></td><td><span class=\"kw-chiffre\">5 %</span> — très bon pronostic</td></tr>\n          <tr><td>Nodule <strong>hyperfonctionnel</strong> (risque d'<span class=\"kw-def\">hyperthyroïdie</span>)</td><td><span class=\"kw-chiffre\">10 %</span></td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Un nodule est <strong>soit bénin, soit malin</strong> : la <span class=\"kw-alerte\">transformation d'un nodule bénin en malin n'est pas possible</span> (ou exceptionnelle). C'est ce qui justifie le simple <strong>suivi</strong> des nodules considérés comme bénins.</div>\n\n      <p><strong>Épidémiologie :</strong> prédominance féminine (<span class=\"kw-chiffre\">3-4 F / 1 H</span>) ; prévalence augmentant avec l'âge — clinique (nodule palpable) <span class=\"kw-chiffre\">4-7 %</span> chez la femme, échographique <span class=\"kw-chiffre\">20 %</span> (et &gt;<span class=\"kw-chiffre\"> 50 %</span> chez la femme de plus de <span class=\"kw-chiffre\">50 ans</span>).</p>","frequence":0},{"id":"241-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les deux problématiques à résoudre en présence d’un nodule thyroïdien","contenu":"<p>Devant tout nodule thyroïdien, deux questions — et seulement deux — guident toute l'exploration.</p>\n\n      <table >\n        <thead><tr><th>Problématique</th><th>Objectif</th><th>Examen pivot</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>1 · Le nodule est-il hyperfonctionnel ?</strong></td>\n            <td>Dépister un nodule à risque d'<span class=\"kw-clinique\">hyperthyroïdie</span>.</td>\n            <td><span class=\"kw-bio\">TSH</span> (± <span class=\"kw-imagerie\">scintigraphie</span> si <span class=\"kw-bio\">TSH</span> basse).</td>\n          </tr>\n          <tr>\n            <td><strong>2 · Le nodule est-il malin ?</strong></td>\n            <td><span class=\"kw-alerte\">Ne pas passer à côté d'un cancer</span>.</td>\n            <td><span class=\"kw-imagerie\">Échographie EU-TIRADS</span> ± <span class=\"kw-bio\">cytoponction</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\"><strong>À retenir.</strong> Il n'est <span class=\"kw-alerte\">pas utile d'explorer les nodules de moins de <span class=\"kw-chiffre\">1 cm</span></span> de diamètre, sauf contexte particulier (irradiation, contexte familial de CMT…).</div>","frequence":2},{"id":"241-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments de l’interrogatoire et de l’examen clinique permettant la découverte et l’évaluation initiale d’un nodule","contenu":"<table >\n        <thead><tr><th>Étape</th><th>Éléments</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Circonstances de découverte</strong></td>\n            <td>\n              <strong>Palpation cervicale</strong> (patient ou médecin) : <span class=\"kw-chiffre\">40-50 %</span><br>\n              <strong>Découverte fortuite</strong> sur une imagerie : <span class=\"kw-chiffre\">30-40 %</span><br>\n              <strong>Dysthyroïdie révélatrice</strong> : <span class=\"kw-chiffre\">15 %</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Interrogatoire</strong></td>\n            <td>\n              Rechercher des symptômes d'<span class=\"kw-clinique\">hyperthyroïdie</span> ; des symptômes de cancer médullaire (<span class=\"kw-clinique\">flush</span>, <span class=\"kw-clinique\">diarrhée motrice</span>).<br>\n              Facteurs de risque de malignité : <span class=\"kw-alerte\">âge &lt; 16 ans</span> ; <span class=\"kw-alerte\">irradiation cervicale dans l'enfance</span> ; <span class=\"kw-alerte\">NEM2</span> ; <span class=\"kw-alerte\">ATCD familiaux de cancer médullaire thyroïdien</span>.\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Palpation cervicale</strong></td>\n            <td>\n              Les nodules cancéreux ne diffèrent <strong>pas</strong> des bénins la plupart du temps. Signes suspects : nodule <span class=\"kw-alerte\">très ferme ou dur</span>, <span class=\"kw-alerte\">irrégulier</span> ; diamètre <span class=\"kw-alerte\">&gt; 3-4 cm</span> ; augmentation de volume <span class=\"kw-alerte\">&gt; 20 %/an</span> ; <span class=\"kw-alerte\">adénopathie cervicale</span>.<br>\n              Signes compressifs : <span class=\"kw-alerte\">paralysie récurrentielle</span>, <span class=\"kw-clinique\">dysphagie</span> ; <span class=\"kw-clinique\">dyspnée</span> plus tardive.\n            </td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"241-10","rang":"A","rubrique":"Examens complémentaires","titre":"Connaître les examens complémentaires de première intention pour explorer un nodule thyroïdien","contenu":"<p>Le bilan systématique de tout nodule comporte deux examens : <strong><span class=\"kw-bio\">TSH</span></strong> + <strong><span class=\"kw-imagerie\">échographie thyroïdienne</span></strong> (classification EU-TIRADS 2017).</p>\n\n      <table >\n        <thead><tr><th>Examen</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Dosage de la <span class=\"kw-bio\">TSH</span></strong></td><td>Recherche systématique d'une dysthyroïdie.</td></tr>\n          <tr><td><strong><span class=\"kw-imagerie\">Échographie thyroïdienne</span></strong></td><td>Systématique — plus sensible que la palpation ; classe le risque (EU-TIRADS).</td></tr>\n          <tr><td><span class=\"kw-bio\">Calcitonine</span> (CT)</td><td><strong>Non systématique</strong> : indiquée si contexte héréditaire de CMT, suspicion de malignité à la cytoponction, ou avant toute intervention pour goitre/nodule. L'<span class=\"kw-bio\">ACE</span> n'est dosé que si la CT est élevée.</td></tr>\n        </tbody>\n      </table>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Évaluation dans un 2ⁿᵈ temps — selon la <span class=\"kw-bio\">TSH</span></h4>\n      <table >\n        <thead><tr><th><span class=\"kw-bio\">TSH</span></th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-bio\">TSH</span> basse</strong></td><td><span class=\"kw-bio\">T4L</span> + <span class=\"kw-bio\">TRAK</span> + <span class=\"kw-imagerie\">scintigraphie à l'iode 123</span>. <span class=\"kw-alerte\">Pas de cytoponction</span>, même si signes échographiques de malignité.</td></tr>\n          <tr><td><strong><span class=\"kw-bio\">TSH</span> normale ou haute</strong></td><td><span class=\"kw-bio\">T4L</span> + <span class=\"kw-bio\">AC anti-TPO</span> + <strong><span class=\"kw-bio\">cytoponction</span></strong> si nodule <span class=\"kw-chiffre\">&gt; 1 cm</span> et EU-TIRADS 3/4/5 (objectif : éliminer un cancer).</td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 242 — <span class=\"kw-def\">Hyperthyroïdie</span></em></p>","frequence":3},{"id":"241-11","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître la place et la cytologie dans la prise en charge d’un nodule thyroïdien","contenu":"<p>La <strong><span class=\"kw-bio\">cytoponction à l'aiguille fine</span></strong> (sous contrôle échographique, moins invasive qu'une <span class=\"kw-bio\">biopsie</span>) est l'examen qui dépiste les cancers thyroïdiens. Son interprétation suit la <strong><span class=\"kw-def\">classification de Bethesda 2017</span></strong>.</p>\n\n      <div class=\"callout callout-info\"><strong>Indications.</strong> La cytoponction est réalisée si <strong>les 3 critères</strong> sont réunis : nodule <span class=\"kw-chiffre\">&gt; 1 cm</span> ; <strong>composante solide</strong> ; nodule échographiquement <strong>suspect</strong> (EU-TIRADS 3-4-5). Autres situations : nodules découverts en <span class=\"kw-imagerie\"><span class=\"kw-imagerie\">TEP</span>-FDG</span> (malins dans <span class=\"kw-chiffre\">30-40 %</span>), nodules &gt;<span class=\"kw-chiffre\"> 15-20 mm</span> peu suspects.</div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Système Bethesda 2017</h4>\n      <table >\n        <thead><tr><th>Catégorie</th><th>Risque de malignité</th><th>Conduite à tenir</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Bethesda I</strong> — non diagnostique</td><td><span class=\"kw-chiffre\">1-4 %</span></td><td>2ᵉ cytoponction à<span class=\"kw-chiffre\"> 3 mois</span>.</td></tr>\n          <tr><td><strong>Bethesda II</strong> — bénin</td><td><span class=\"kw-chiffre\">0-3 %</span></td><td>Surveillance échographique.</td></tr>\n          <tr><td><strong>Bethesda III</strong> — atypies / lésion folliculaire de signification indéterminée</td><td><span class=\"kw-chiffre\">5-15 %</span></td><td>2ᵉ cytoponction à<span class=\"kw-chiffre\"> 3 mois</span> ou chirurgie.</td></tr>\n          <tr><td><strong>Bethesda IV</strong> — néoplasme folliculaire / oncocytaire</td><td><span class=\"kw-chiffre\">15-30 %</span></td><td>Chirurgie.</td></tr>\n          <tr><td><strong>Bethesda V</strong> — suspect de malignité</td><td><span class=\"kw-chiffre\">60-75 %</span></td><td>Chirurgie.</td></tr>\n          <tr><td><strong>Bethesda VI</strong> — malin</td><td><span class=\"kw-chiffre\">97-99 %</span></td><td><span class=\"kw-alerte\">Thyroïdectomie totale</span>.</td></tr>\n        </tbody>\n      </table>","frequence":2},{"id":"241-12","rang":"B","rubrique":"Définition","titre":"Connaître les principaux types histologiques des cancers thyroïdiens","contenu":"<p>Le cancer thyroïdien représente <span class=\"kw-chiffre\">1,5 %</span> des cancers (cancer endocrinien le plus fréquent), survient à <span class=\"kw-chiffre\">75 %</span> chez la femme, et son pronostic d'ensemble est bon (survie à<span class=\"kw-chiffre\"> 10 ans</span> &gt;<span class=\"kw-chiffre\"> 90 %</span>). Les types histologiques se répartissent selon la cellule d'origine.</p>\n\n      <table >\n        <thead><tr><th>Cellule d'origine</th><th>Marqueur</th><th>Types histologiques</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><strong>Cellules folliculaires</strong> (épithéliales)</td>\n            <td><span class=\"kw-bio\">Thyroglobuline</span></td>\n            <td>\n              <span class=\"kw-def\">Carcinome papillaire</span> différencié — <span class=\"kw-chiffre\">85 %</span><br>\n              <span class=\"kw-def\">Carcinome vésiculaire</span> différencié — <span class=\"kw-chiffre\">5 %</span><br>\n              Carcinomes peu différenciés et oncocytaires — <span class=\"kw-chiffre\">2-5 %</span><br>\n              <span class=\"kw-alerte\">Carcinome anaplasique</span> — <span class=\"kw-chiffre\">1 %</span>\n            </td>\n          </tr>\n          <tr>\n            <td><strong>Cellules C</strong> (parafolliculaires)</td>\n            <td><span class=\"kw-bio\">Calcitonine</span> + <span class=\"kw-bio\">ACE</span></td>\n            <td><span class=\"kw-def\">Carcinome médullaire</span> (CMT) — <span class=\"kw-chiffre\">5 %</span>. Tumeur neuroendocrine.</td>\n          </tr>\n          <tr>\n            <td><strong>Autres</strong></td>\n            <td>—</td>\n            <td>Lymphomes (sur <span class=\"kw-def\">thyroïdite</span> de Hashimoto) ; métastases thyroïdiennes (notamment cancer du rein à cellules claires) — <span class=\"kw-chiffre\">1 %</span>.</td>\n          </tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\"><strong>Discriminant — selon l'âge.</strong> Chez le <strong>sujet jeune</strong>, le cancer est <span class=\"kw-alerte\">toujours différencié</span>, presque toujours un carcinome papillaire d'excellent pronostic. Chez le <strong>sujet âgé</strong>, possibilité de cancers <span class=\"kw-alerte\">peu différenciés ou anaplasiques</span> de très mauvais pronostic.</div>\n\n      <div class=\"callout callout-warn\"><strong>Réflexe.</strong> Devant un carcinome médullaire, la recherche d'une mutation du gène <strong><span class=\"kw-def\">RET</span></strong> est <strong>systématique</strong> : <span class=\"kw-def\">NEM2</span> (transmission autosomique dominante) est retrouvée dans <span class=\"kw-chiffre\">25-30 %</span> des CMT — associée à un phéochromocytome et/ou une hyperparathyroïdie.</div>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 245 — Insuffisance surrénale · 268 — Hypercalcémie</em></p>","frequence":2},{"id":"241-13","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes de la prise en charge du goitre et des nodules (à l’exception du cancer)","contenu":"<p>Avant toute décision, les options thérapeutiques et de surveillance sont présentées et discutées avec le patient au cas par cas. Le <strong>meilleur traitement reste la prévention</strong> par un apport iodé suffisant pendant l'adolescence et la grossesse.</p>\n\n      <h4 style=\"margin:4px 0 6px;font-size:14px;\">Goitre — options</h4>\n      <table >\n        <thead><tr><th>Option</th><th>Modalités</th></tr></thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-ttt\">Traitement thyroxinique</span></strong></td><td>Discuté au stade de <strong>goitre simple</strong> ou pendant la <strong>grossesse</strong>. <span class=\"kw-ci\">Contre-indiqué au stade de goitre nodulaire</span> (risque d'<span class=\"kw-def\">hyperthyroïdie</span> : lésions irréversibles, goitre déjà partiellement autonome).</td></tr>\n          <tr><td><strong>Surveillance</strong></td><td>Possible si tous les critères sont réunis : goitre nodulaire/multinodulaire ; <strong>euthyroïdien</strong> ; <strong>non compressif</strong> ; <strong>sans suspicion de malignité</strong>.</td></tr>\n          <tr><td><strong>Chirurgie</strong></td><td>Indications : goitre symptomatique ; nodule suspect (thyroïdectomie totale/partielle ± curage) ; Basedow et goitre multinodulaire toxique (thyroïdectomie totale) ; adénome toxique (lobectomie du côté lésé). Préparation par <span class=\"kw-ttt\">antithyroïdiens de synthèse</span><span class=\"kw-chiffre\"> 2-3 mois</span> si <span class=\"kw-def\">hyperthyroïdie</span> (euthyroïdie, prévention de la crise aiguë thyrotoxique).</td></tr>\n          <tr><td><strong><span class=\"kw-ttt\">Iode 131</span></strong> (dose thérapeutique)</td><td>Alternative à la chirurgie en cas d'<span class=\"kw-def\">hyperthyroïdie</span> ou de goitre compressif chez le sujet âgé ou en mauvais état général ; réduit le volume du goitre de <span class=\"kw-chiffre\">30-40 %</span>.</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-danger\"><strong>Complications post-opératoires</strong> (<span class=\"kw-chiffre\">1 à 3 %</span> des cas) : <span class=\"kw-alerte\">hématome suffocant</span> dans les <span class=\"kw-chiffre\">48 h</span> (dégrafage immédiat) ; <span class=\"kw-alerte\">hypothyroïdie définitive</span> (substitution par <span class=\"kw-ttt\">lévothyroxine</span> à vie) ; <span class=\"kw-alerte\">paralysie récurrentielle</span> (dysphonie ; <span class=\"kw-clinique\">dyspnée</span> laryngée si bilatérale) ; <span class=\"kw-alerte\">hypoparathyroïdie</span> après thyroïdectomie totale (calcium + <span class=\"kw-bio\">vitamine D</span> active).</div>\n\n      <h4 style=\"margin:14px 0 6px;font-size:14px;\">Nodules — prise en charge selon le statut</h4>\n      <table >\n        <thead><tr><th>Situation</th><th>Conduite</th></tr></thead>\n        <tbody>\n          <tr><td><strong>Nodule hyperfonctionnel</strong></td><td>Chirurgie (lobectomie unilatérale possible si l'autre lobe est sain) ou <span class=\"kw-ttt\">iode 131</span> chez les patients âgés/fragiles.</td></tr>\n          <tr><td><strong>Bethesda II</strong> (bénin)</td><td>Surveillance <strong>clinique + échographique</strong>, annuelle puis tous les <span class=\"kw-chiffre\">3 à 5 ans</span>. Chirurgie discutée si nodule volumineux (<span class=\"kw-chiffre\">&gt; 40 mm</span>), gêne fonctionnelle, ou progression régulière de taille.</td></tr>\n          <tr><td><strong>Bethesda III / IV</strong></td><td>Chirurgie <strong>non systématique</strong> : discutée au cas par cas avec le patient selon le contexte.</td></tr>\n          <tr><td><strong>Bethesda V / VI</strong></td><td><span class=\"kw-alerte\">Chirurgie nécessaire</span>.</td></tr>\n        </tbody>\n      </table>\n\n      <p class=\"obj-renvois\"><em>📎 Items liés : 242 — <span class=\"kw-def\">Hyperthyroïdie</span></em></p>","frequence":3}],"astuces":[],"strategie":{"urgence":"<p><strong>Pathologie peu urgente :</strong> la majorité des goitres et nodules relèvent d'un <span class=\"kw-imagerie\">bilan ambulatoire</span> (<span class=\"kw-bio\">TSH</span> + <span class=\"kw-imagerie\">échographie</span>), sans urgence.<br><strong>Carcinome anaplasique :</strong> <span class=\"kw-clinique\">tuméfaction cervicale rapidement progressive, dure, adhérente</span> du <span class=\"kw-etio\">sujet âgé</span> sur goitre ancien → <span class=\"kw-ttt\">radiochimiothérapie en urgence</span> (souvent déjà métastatique, <span class=\"kw-alerte\">pronostic très péjoratif</span>, survie à<span class=\"kw-chiffre\"> 1 an</span> <span class=\"kw-chiffre\">15 %</span>).<br><strong>Goitre compressif :</strong> <span class=\"kw-alerte\">signes compressifs</span> (<span class=\"kw-clinique\">dyspnée, dysphonie, dysphagie</span>) imposant exploration et PEC sans délai.<br><strong>Post-thyroïdectomie :</strong> <span class=\"kw-alerte\">hématome suffocant</span> dans les <span class=\"kw-chiffre\">48 h</span> → <span class=\"kw-ttt\">dégrafage immédiat</span> de la cervicotomie.<br><strong>NEM2 :</strong> <span class=\"kw-alerte\">phéochromocytome méconnu</span> → <span class=\"kw-alerte\">collapsus cardiovasculaire</span> à l'induction anesthésique → <span class=\"kw-ttt\">dosage préopératoire des métanéphrines</span> en cas de suspicion de CMT.</p>","hospit":"<p><strong>Ambulatoire :</strong> bilan diagnostique initial (<span class=\"kw-bio\">TSH</span> + <span class=\"kw-imagerie\">échographie</span> ± <span class=\"kw-imagerie\">cytoponction</span>) et surveillance des nodules bénins.<br><strong>RCP :</strong> l'indication de l'<span class=\"kw-ttt\">IRAthérapie (iode 131)</span> est discutée en réunion de concertation pluridisciplinaire.<br><strong>Hospitalisation protégée :</strong> <span class=\"kw-ttt\">IRAthérapie</span> en <span class=\"kw-imagerie\">chambre radioprotégée</span> pendant <span class=\"kw-chiffre\">2 à 5 jours</span> (obligatoire dès <span class=\"kw-chiffre\">> 20 mCi</span>).<br><strong>Oncogénétique :</strong> en cas de <span class=\"kw-etio\">mutation RET</span> (CMT), <span class=\"kw-ttt\">consultation d'oncogénétique</span> + enquête familiale chez les apparentés (<span class=\"kw-ttt\">thyroïdectomie prophylactique</span> possible).</p>","redflags":"<ul><li><span class=\"kw-clinique\">Nodule très ferme ou dur, irrégulier</span></li><li>Nodule de <span class=\"kw-chiffre\">> 3-4 cm</span> de diamètre</li><li>Augmentation du volume <span class=\"kw-chiffre\">> 20 %/an</span></li><li><span class=\"kw-clinique\">Adénopathie cervicale</span></li><li><span class=\"kw-alerte\">Signes compressifs</span> : <span class=\"kw-clinique\">paralysie récurrentielle, dysphonie, dysphagie</span>, puis <span class=\"kw-clinique\">dyspnée</span></li><li>Âge <span class=\"kw-chiffre\">< 16 ans</span></li><li><span class=\"kw-etio\">Irradiation cervicale dans l'enfance</span> (risque de cancer thyroïdien <span class=\"kw-chiffre\">× 7</span>)</li><li>Contexte de <span class=\"kw-etio\">NEM2</span> ou <span class=\"kw-etio\">ATCD familiaux de cancer médullaire thyroïdien</span></li><li><span class=\"kw-clinique\">Flush, diarrhée motrice</span> évoquant un <span class=\"kw-etio\">carcinome médullaire</span></li><li>Croissance rapide d'un goitre ou d'une zone pseudo-nodulaire sur thyroïdite → évoquer un <span class=\"kw-etio\">lymphome</span></li><li>Échographie <span class=\"kw-radio\">EU-TIRADS 5</span> : nodule <span class=\"kw-radio\">très hypoéchogène, plus haut que large, à marges irrégulières, microcalcifications</span></li></ul>","principes":"<p>PEC orientée par le <span class=\"kw-bio\">statut fonctionnel (TSH)</span> et le <span class=\"kw-bio\">résultat cytologique (Bethesda)</span>, discutée au cas par cas avec le patient pour limiter le surdiagnostic.</p><p><strong>Nodule hyperfonctionnel (<span class=\"kw-bio\">TSH</span> basse)</strong></p><ul><li><span class=\"kw-ttt\">Chirurgie</span> : <span class=\"kw-ttt\">lobectomie unilatérale</span> possible s'il n'y a pas de nodule controlatéral</li><li><span class=\"kw-ttt\">Iode radioactif 131</span> chez les patients <span class=\"kw-etio\">âgés ou fragiles</span></li></ul><p><strong>Nodule Bethesda II (bénin)</strong></p><ul><li><span class=\"kw-ttt\">Surveillance clinique + échographique</span> : <span class=\"kw-chiffre\">annuelle</span> puis tous les <span class=\"kw-chiffre\">3 à 5 ans</span></li><li><span class=\"kw-ttt\">Chirurgie</span> discutée si nodule <span class=\"kw-chiffre\">> 40 mm</span>, <span class=\"kw-clinique\">gêne fonctionnelle</span> ou <span class=\"kw-clinique\">progression régulière</span></li></ul><p><strong>Nodule Bethesda III/IV (indéterminé)</strong></p><ul><li><span class=\"kw-ttt\">Chirurgie</span> non systématique, discutée au cas par cas avec le patient selon le contexte</li></ul><p><strong>Nodule Bethesda V/VI (suspect / malin)</strong></p><ul><li><span class=\"kw-ttt\">Chirurgie</span> nécessaire : <span class=\"kw-ttt\">thyroïdectomie totale</span> si Bethesda VI</li></ul><p><strong>Goitre</strong></p><ul><li><span class=\"kw-ttt\">Surveillance</span> si goitre euthyroïdien, non compressif, sans suspicion de malignité</li><li><span class=\"kw-ttt\">Lévothyroxine</span> discutée au stade de <span class=\"kw-def\">goitre simple</span> ou pendant la <span class=\"kw-etio\">grossesse</span></li><li><span class=\"kw-ci\">Lévothyroxine contre-indiquée au stade de goitre nodulaire</span> (risque d'hyperthyroïdie)</li><li><span class=\"kw-ttt\">Chirurgie</span> ou <span class=\"kw-ttt\">iode 131</span> si goitre symptomatique/compressif</li><li>Meilleur traitement = <span class=\"kw-ttt\">prévention par apport iodé suffisant</span> (adolescence, grossesse)</li></ul><p><strong>Cancers différenciés (papillaire / vésiculaire)</strong></p><ul><li><span class=\"kw-ttt\">Chirurgie</span> = traitement de 1ère intention de presque tous les cancers thyroïdiens</li><li><span class=\"kw-ttt\">IRAthérapie (iode 131)</span> si <span class=\"kw-ttt\">thyroïdectomie totale</span> + <span class=\"kw-etio\">forme à haut risque de récidive</span> (RCP)</li><li><span class=\"kw-ttt\">Freination par lévothyroxine</span> (dose légèrement supraphysiologique) si haut risque / forme récidivante ou métastatique</li></ul><p><strong>Cancer médullaire (CMT)</strong></p><ul><li><span class=\"kw-ttt\">Thyroïdectomie totale + curage ganglionnaire</span></li><li><span class=\"kw-ttt\">Lévothyroxine à dose substitutive</span> (pas supraphysiologique)</li><li><span class=\"kw-ci\">Iode radioactif sans intérêt</span> (les cellules C ne fixent pas l'iode)</li><li>Recherche systématique de <span class=\"kw-etio\">mutation RET</span> (<span class=\"kw-etio\">NEM2</span> dans <span class=\"kw-chiffre\">25-30 %</span>)</li></ul>","suivi":"<p><strong>Nodule bénin (Bethesda II) :</strong> surveillance <span class=\"kw-ttt\">clinique + échographique</span>, <span class=\"kw-chiffre\">annuelle</span> puis tous les <span class=\"kw-chiffre\">3 à 5 ans</span>.<br><strong>Cancer différencié :</strong> <span class=\"kw-bio\">TSH</span> (à <span class=\"kw-chiffre\">≥ 6 semaines</span> puis annuelle/biannuelle), <span class=\"kw-bio\">thyroglobuline</span> (doit être indétectable) + <span class=\"kw-bio\">AC anti-thyroglobuline</span>, <span class=\"kw-imagerie\">échographie cervicale</span> (récidive ganglionnaire).<br><strong>Suspicion de récidive métastatique :</strong> <span class=\"kw-imagerie\">TDM thoracique</span> et/ou <span class=\"kw-imagerie\">TEP-FDG</span>.<br><strong>Cancer médullaire :</strong> <span class=\"kw-bio\">calcitonine</span> + <span class=\"kw-bio\">ACE</span> ; calcitonine indosable à <span class=\"kw-chiffre\">3 mois</span> = rémission (surveillance annuelle), détectable = <span class=\"kw-etio\">maladie persistante</span>.<br><strong>Après thyroïdectomie totale :</strong> substitution par <span class=\"kw-ttt\">lévothyroxine</span> au long cours + surveillance de la <span class=\"kw-bio\">calcémie</span> (risque d'<span class=\"kw-etio\">hypoparathyroïdie</span>).</p>"},"liensGlobaux":[{"href":"https://www.sfendocrino.org/item-241-cancers-thyroidiens/","label":"SFE — Item 241 cancers thyroidiens"},{"href":"https://medecine.univ-batna2.dz/sites/default/files/medecine/files/thyroide.pdf","label":"Thyroide"},{"href":"https://www.sfendocrino.org/item-241-goitre-2/","label":"SFE — Item 241 goitre 2"},{"href":"https://toulouse-thyroide.fr/?page_id=233","label":"https://toulouse-thyroide.fr/?page_id=233"},{"href":"https://www.sfendocrino.org/item-241-nodules-thyroidiens/","label":"SFE — Item 241 nodules thyroidiens"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Nodule thyroïdien — 2 objectifs : dépister un nodule hyperfonctionnel + ne pas méconnaître un cancer. Bilan initial : TSH + échographie (EU-TIRADS 2017)","detail":"<h4>CAT — Nodule thyroïdien — Démarche diagnostique et conduite à tenir devant un nodule thyroïdien</h4>","branches":[{"to":"q-tsh","label":"Bilan initial réalisé","color":"blue"}]},{"id":"q-tsh","kind":"decision","label":"Quelle est la valeur de la TSH ? — Dosage systématique en 1ère intention","branches":[{"to":"q-scinti","label":"TSH basse (hyperthyroïdie)","color":"amber"},{"to":"q-cyto-indic","label":"TSH normale ou élevée","color":"blue"}]},{"id":"q-scinti","kind":"decision","label":"Scintigraphie thyroïdienne (iode 123) — T4L + TRAK ; pas de cytoponction dans ce contexte, même si signe de malignité","branches":[{"to":"t-chaud","label":"Nodule chaud (hyperfixant)","color":"green"},{"to":"t-froid","label":"Nodule froid","color":"amber"}]},{"id":"t-chaud","kind":"terminal","label":"Adénome toxique / fonctionnel — Hyperfixation localisée","color":"green","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Chirurgie</span> (<span class=\"kw-ttt\">lobectomie unilatérale</span>) ou <span class=\"kw-ttt\">iode 131</span> si <span class=\"kw-etio\">sujet âgé/fragile</span></li><li>Pas de <span class=\"kw-ttt\">cytoponction</span> nécessaire</li></ul>"},{"id":"t-froid","kind":"terminal","label":"Nodule froid (contexte d'hyperthyroïdie) — Nodule non fixant, fixation diffuse, TRAK élevée","color":"amber","detail":"<h4>Conduite</h4><ul><li>Évoque une <span class=\"kw-etio\">maladie de Basedow</span> associée (<span class=\"kw-bio\">TRAK élevés</span>, <span class=\"kw-bio\">T4L élevée</span>)</li><li>Pas de <span class=\"kw-ttt\">cytoponction</span> même en cas de signe de malignité échographique</li></ul>"},{"id":"q-cyto-indic","kind":"decision","label":"Critères de cytoponction réunis ? — Nodule > 1 cm + composante solide + EU-TIRADS 3/4/5","branches":[{"to":"t-surv-simple","label":"Non","color":"green"},{"to":"q-bethesda","label":"Oui → cytoponction","color":"blue"}]},{"id":"t-surv-simple","kind":"terminal","label":"Surveillance simple — Nodule < 1 cm ou non suspect","color":"green","detail":"<h4>Conduite</h4><ul><li>Pas d'exploration des nodules <span class=\"kw-chiffre\">< 1 cm</span> sauf contexte particulier</li><li><span class=\"kw-ttt\">Surveillance clinique et échographique</span></li></ul>"},{"id":"q-bethesda","kind":"decision","label":"Résultat de la cytoponction (Bethesda) ? — La cytologie de Bethesda dicte la conduite à tenir","branches":[{"to":"t-beth1","label":"Bethesda I","color":"amber"},{"to":"t-beth2","label":"Bethesda II","color":"green"},{"to":"t-beth34","label":"Bethesda III/IV","color":"amber"},{"to":"t-beth56","label":"Bethesda V/VI","color":"red"}]},{"id":"t-beth1","kind":"terminal","label":"Bethesda I — non diagnostique","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">2ᵉ cytoponction</span> à <span class=\"kw-chiffre\">3 mois</span></li></ul>"},{"id":"t-beth2","kind":"terminal","label":"Bethesda II — bénin","color":"green","detail":"<h4>Surveillance</h4><ul><li><span class=\"kw-ttt\">Surveillance clinique + échographique</span> : <span class=\"kw-chiffre\">annuelle</span> puis tous les <span class=\"kw-chiffre\">3 à 5 ans</span></li><li><span class=\"kw-ttt\">Chirurgie</span> discutée si <span class=\"kw-chiffre\">> 40 mm</span>, <span class=\"kw-clinique\">gêne fonctionnelle</span> ou <span class=\"kw-clinique\">progression</span></li></ul>"},{"id":"t-beth34","kind":"terminal","label":"Bethesda III/IV — indéterminé","color":"amber","detail":"<h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Chirurgie</span> non systématique, discutée au cas par cas avec le patient</li></ul>"},{"id":"t-beth56","kind":"terminal","label":"Bethesda V/VI — suspect / malin","color":"red","detail":"<h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Thyroïdectomie</span> (<span class=\"kw-ttt\">totale</span> si Bethesda VI)</li><li>PEC adaptée au type histologique après examen anatomopathologique</li></ul>"}]},"cards":[{"i":"2743cb115dd6","n":241,"o":"241-1","u":"Définition","t":"Connaître la définition d’un goitre","q":"Selon la classification de l'OMS, comment sont définis les grades cliniques d'un goitre?","a":"<ul><li><strong>Grade 0</strong> : Thyroïde non palpable et non visible (situation normale).</li><li><strong>Grade 1</strong> : Goitre <strong>palpable mais non visible</strong>, cou en position normale. Les nodules d'une thyroïde non hypertrophiée entrent aussi dans cette catégorie.</li><li><strong>Grade 2</strong> : Goitre <strong>nettement visible</strong>, cou en position normale.</li></ul>"},{"i":"87b57400b657","n":241,"o":"241-1","u":"Définition","t":"Connaître la définition d’un goitre","q":"Quels sont les seuils échographiques pour définir un goitre?","a":"<ul><li>Chez l'adolescent : un volume thyroïdien <strong>> 16 mL</strong>.</li><li>Chez la femme : un volume thyroïdien <strong>> 18 mL</strong>.</li><li>Chez l'homme : un volume thyroïdien <strong>> 20 mL</strong>.</li></ul>"},{"i":"91fdbdb719eb","n":241,"o":"241-1","u":"Définition","t":"Connaître la définition d’un goitre","q":"Quelle est la définition d'un goitre?","a":"<p>Un goitre est une <strong>augmentation du volume de la glande thyroïde</strong>, qui peut être diffuse ou localisée (goitre nodulaire).</p>"},{"i":"f8453593ec91","n":241,"o":"241-1","u":"Définition","t":"Connaître la définition d’un goitre","q":"Comment définit-on cliniquement le seuil d'un goitre à la palpation?","a":"<p>Cliniquement, un goitre est défini lorsque la surface de chacun des lobes thyroïdiens <strong>excède celle de la dernière phalange du pouce du patient</strong> lors de la palpation.</p>"},{"i":"fc01ab56dad7","n":241,"o":"241-1","u":"Définition","t":"Connaître la définition d’un goitre","q":"Le fonctionnement thyroïdien est-il affecté par la présence d'un goitre?","a":"<p>Non, l'existence d'un goitre ne préjuge pas du fonctionnement thyroïdien. La thyroïde peut être <strong>euthyroïdienne</strong>, <strong>hypothyroïdienne</strong> ou <strong>hyperthyroïdienne</strong>.</p>"},{"i":"03878ae2907f","n":241,"o":"241-10","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention pour explorer un nodule thyroïdien","q":"Quels sont les deux examens complémentaires de première intention à réaliser systématiquement face à un nodule thyroïdien, d'après les recommandations ?","a":"<p>Les deux examens de première intention systématiques sont :</p><ul><li>Le dosage de la <strong>TSH</strong>.</li><li>L'<strong>échographie thyroïdienne</strong>, avec classification selon l'<strong>EU-TIRADS 2017</strong>.</li></ul>"},{"i":"1cb889f50355","n":241,"o":"241-10","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention pour explorer un nodule thyroïdien","q":"Quelle est la stratégie d'exploration complémentaire d'un nodule thyroïdien si la TSH est basse ?","a":"<p>Si la TSH est basse, la stratégie est la suivante :</p><ul><li>Dosage de la <strong>T4L</strong> et des <strong>TRAK</strong>.</li><li>Réalisation d'une <strong>scintigraphie à l'iode 123</strong>.</li><li><strong>Pas de cytoponction</strong>, même en présence de signes échographiques de malignité.</li></ul>"},{"i":"25e05410c0d3","n":241,"o":"241-10","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention pour explorer un nodule thyroïdien","q":"Dans quel(s) contexte(s) clinique(s) le dosage de la Calcitonine (CT) est-il indiqué lors de l'exploration d'un nodule thyroïdien ?","a":"<p>Le dosage de la Calcitonine (CT) <strong>n'est pas systématique</strong>. Il est indiqué dans les contextes suivants :</p><ul><li>Contexte héréditaire de <strong>carcinome médullaire de la thyroïde (CMT)</strong>.</li><li>Suspicion de malignité à la <strong>cytoponction</strong>.</li><li>Avant toute intervention chirurgicale pour un goitre ou un nodule.</li></ul>"},{"i":"69813b9d60d3","n":241,"o":"241-10","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention pour explorer un nodule thyroïdien","q":"Quel est l'objectif de la cytoponction thyroïdienne dans le cadre de l'exploration d'un nodule à TSH normale ou haute ?","a":"<p>L'objectif principal de la cytoponction thyroïdienne dans ce contexte est d'<strong>éliminer un cancer</strong> thyroïdien.</p>"},{"i":"d75187c4c8c9","n":241,"o":"241-10","u":"Examens complémentaires","t":"Connaître les examens complémentaires de première intention pour explorer un nodule thyroïdien","q":"Quelle est la stratégie d'exploration complémentaire d'un nodule thyroïdien si la TSH est normale ou haute ?","a":"<p>Si la TSH est normale ou haute, la stratégie est la suivante :</p><ul><li>Dosage de la <strong>T4L</strong> et des <strong>AC anti-TPO</strong>.</li><li>Réalisation d'une <strong>cytoponction</strong> si le nodule est <strong>supérieur à 1 cm</strong> et classé <strong>EU-TIRADS 3, 4 ou 5</strong>, dans l'objectif d'éliminer un cancer thyroïdien.</li></ul>"},{"i":"60e4228d4a36","n":241,"o":"241-2","u":"Examens complémentaires","t":"Connaître l’indications des examens d’imagerie devant un goitre, un ou des nodules","q":"Que signifie une hyperfixation localisée à la scintigraphie thyroïdienne ?","a":"<p>Une hyperfixation localisée à la scintigraphie thyroïdienne oriente vers un <strong>nodule chaud</strong> ou un <strong>adénome toxique</strong>.</p>"},{"i":"72baa8ea2d10","n":241,"o":"241-2","u":"Examens complémentaires","t":"Connaître l’indications des examens d’imagerie devant un goitre, un ou des nodules","q":"Pourquoi un scanner injecté doit-il être évité dans le bilan d'un cancer thyroïdien avancé ?","a":"<p>Un scanner injecté doit être évité car la <strong>surcharge en iode</strong> qu'il entraîne peut compromettre l'efficacité d'une future <strong>IRAthérapie</strong>.</p>"},{"i":"84fd9d4e6191","n":241,"o":"241-2","u":"Examens complémentaires","t":"Connaître l’indications des examens d’imagerie devant un goitre, un ou des nodules","q":"Quelle est l'indication principale de l'échographie thyroïdienne dans l'exploration d'un goitre ou d'un nodule ?","a":"<p>L'échographie thyroïdienne est indiquée <strong>systématiquement devant tout nodule</strong> (plus sensible que la palpation) et est utile devant un <strong>goitre irrégulier</strong> pour rechercher des nodules.</p>"},{"i":"88487329e44d","n":241,"o":"241-2","u":"Examens complémentaires","t":"Connaître l’indications des examens d’imagerie devant un goitre, un ou des nodules","q":"Dans quel contexte la scintigraphie thyroïdienne est-elle indiquée et quelles en sont les contre-indications ?","a":"<p>La scintigraphie (I123 ou Tc99m) est indiquée <strong>uniquement en cas d'hyperthyroïdie</strong> (TSH basse). Elle est contre-indiquée pendant la <strong>grossesse</strong> et l'<strong>allaitement</strong>.</p>"},{"i":"a49c0f7fba09","n":241,"o":"241-2","u":"Examens complémentaires","t":"Connaître l’indications des examens d’imagerie devant un goitre, un ou des nodules","q":"Quels sont les facteurs échographiques de malignité selon la classification EU-TIRADS 2017 ?","a":"<ul><li><strong>Hypoéchogénicité</strong></li><li><strong>Microcalcifications</strong></li><li>Caractère <strong>mal limité</strong></li><li>Forme <strong>non ovalaire</strong> (plus haute que large)</li></ul>"},{"i":"ce54ce8def98","n":241,"o":"241-2","u":"Examens complémentaires","t":"Connaître l’indications des examens d’imagerie devant un goitre, un ou des nodules","q":"Pour le bilan d'extension des cancers thyroïdiens qui ne fixent pas l'iode, quel examen d'imagerie est recommandé et avec quel traceur ?","a":"<p>Pour ces cancers, un <strong>TEP-TDM</strong> est recommandé :</p><ul><li><strong>TEP-FDG</strong> pour les cancers épithéliaux.</li><li><strong>TEP-F-DOPA</strong> pour le cancer médullaire.</li></ul>"},{"i":"d663cd6797e5","n":241,"o":"241-2","u":"Examens complémentaires","t":"Connaître l’indications des examens d’imagerie devant un goitre, un ou des nodules","q":"Dans quels cas un scanner cervico-thoracique (TDM) est-il pertinent dans l'évaluation d'une pathologie thyroïdienne ?","a":"<p>Une TDM cervico-thoracique est indiquée pour le <strong>bilan d'un goitre plongeant</strong> et pour le <strong>bilan d'extension d'un cancer thyroïdien avancé</strong> (recherche d'adénopathies médiastinales ou de métastases pulmonaires).</p>"},{"i":"61d15bcb028b","n":241,"o":"241-4","u":"Diagnostic positif","t":"Connaître les trois principaux diagnostics étiologiques de goitres","q":"Quelle est l'approche diagnostique initiale essentielle pour explorer l'étiologie d'un goitre ?","a":"<p>L'approche diagnostique initiale repose sur le dosage de la <strong>TSH</strong> et la réalisation d'une <strong>échographie thyroïdienne</strong>.</p>"},{"i":"a92d968a9c23","n":241,"o":"241-4","u":"Diagnostic positif","t":"Connaître les trois principaux diagnostics étiologiques de goitres","q":"Quelles sont les spécificités cliniques et biologiques de la maladie de Basedow, une cause fréquente de goitre ?","a":"<ul><li>La TSH est <strong>basse</strong>.</li><li>Elle touche la <strong>femme jeune</strong>.</li><li>Elle se présente avec un <strong>goitre diffus</strong> et une <strong>hyperthyroïdie</strong>, et peut s'associer à des signes extrathyroïdiens comme l'<strong>orbitopathie</strong>.</li><li>Le diagnostic est confirmé par le dosage des <strong>AC anti-récepteurs de la TSH (TRAK)</strong>.</li></ul>"},{"i":"ae91db3b4b7d","n":241,"o":"241-4","u":"Diagnostic positif","t":"Connaître les trois principaux diagnostics étiologiques de goitres","q":"Quelles sont les caractéristiques principales du goitre simple, l'une des étiologies dominantes de goitre ?","a":"<ul><li>Il est la <strong>majorité des cas</strong> de goitre.</li><li>La TSH est <strong>normale</strong>.</li><li>Il se caractérise par une <strong>hypertrophie diffuse et homogène</strong> du parenchyme thyroïdien, souple, débutant à l'adolescence.</li><li>Il est <strong>normofonctionnel et non inflammatoire</strong>.</li><li>Il peut évoluer vers une forme multinodulaire.</li><li>Les anticorps anti-thyroïdiens sont <strong>négatifs</strong>.</li></ul>"},{"i":"f959b912a735","n":241,"o":"241-4","u":"Diagnostic positif","t":"Connaître les trois principaux diagnostics étiologiques de goitres","q":"Comment se manifeste la thyroïdite de Hashimoto, l'une des principales étiologies de goitre ?","a":"<ul><li>La TSH est <strong>élevée</strong>.</li><li>C'est une <strong>thyroïdite auto-immune</strong> touchant la femme de <strong>40-60 ans</strong>.</li><li>Le goitre est <strong>irrégulier, ferme et pseudo-nodulaire</strong>.</li><li>C'est la <strong>1<sup>re</sup> cause d'hypothyroïdie</strong> en France.</li><li>Le diagnostic est confirmé par la présence d'<strong>AC anti-TPO à titre élevé (+++)</strong>, parfois associés à des AC anti-Tg.</li></ul>"},{"i":"04a69858ff08","n":241,"o":"241-5","u":"Diagnostic positif","t":"Connaître les trois principales complications évolutives d’un goitre","q":"Quelle est la physiopathologie de l'hyperthyroïdie par autonomisation dans le cadre d'un goitre ?","a":"<p>L'hyperthyroïdie par autonomisation résulte de l'<strong>autonomisation progressive de nodules hyperfonctionnels</strong> au sein du goitre, conduisant à un <strong>goitre multinodulaire toxique</strong>.</p>"},{"i":"3ad7da8d17f0","n":241,"o":"241-5","u":"Diagnostic positif","t":"Connaître les trois principales complications évolutives d’un goitre","q":"Quels sont les signes cliniques de la complication compressive d'un goitre ?","a":"<p>La complication compressive d'un goitre peut se manifester par :</p><ul><li>Des <strong>troubles de la déglutition</strong>.</li><li>Une <strong>dysphonie</strong>.</li><li>Une <strong>gêne respiratoire</strong>.</li><li>Plus rarement une <strong>compression veineuse</strong> (syndrome cave supérieur).</li></ul><p>Le <strong>goitre plongeant</strong> est une forme où cette compression s'étend au médiastin.</p>"},{"i":"e3134f4a4e0d","n":241,"o":"241-5","u":"Diagnostic positif","t":"Connaître les trois principales complications évolutives d’un goitre","q":"Quelle est la fréquence de la complication de cancérisation au sein d'un goitre plurinodulaire ?","a":"<p>Un cancer est présent dans <strong>4 à 5 %</strong> des goitres plurinodulaires.</p>"},{"i":"ec3196d47639","n":241,"o":"241-5","u":"Diagnostic positif","t":"Connaître les trois principales complications évolutives d’un goitre","q":"Quels examens d'imagerie sont utiles devant un goitre plongeant et que montrent-ils généralement ?","a":"<p>Devant un goitre plongeant :</p><ul><li>La <strong>radiographie thoracique (RXT)</strong> montre un <strong>élargissement du médiastin supérieur antérieur</strong> et une <strong>déviation trachéale</strong>.</li><li>La <strong>TDM</strong> ou l'<strong>IRM</strong> confirment une lésion en <strong>continuité avec la thyroïde</strong>, souvent <strong>calcifiée</strong>.</li></ul>"},{"i":"fd8c50ec9c30","n":241,"o":"241-5","u":"Diagnostic positif","t":"Connaître les trois principales complications évolutives d’un goitre","q":"Quelles sont les trois principales complications évolutives d'un goitre, notamment s'il est multinodulaire et ancien ?","a":"<p>Les trois principales complications évolutives d'un goitre sont :</p><ul><li>La <strong>compression</strong> des structures adjacentes.</li><li>L'<strong>hyperthyroïdie par autonomisation</strong>.</li><li>La <strong>cancérisation</strong>.</li></ul>"},{"i":"08e41c59ce38","n":241,"o":"241-6","u":"Examens complémentaires","t":"Connaître les examens complémentaires à réaliser en première intention en présence d’un goitre","q":"La recherche d'anticorps anti-thyroglobuline est-elle pertinente dans le bilan de première intention d'un goitre ?","a":"<p>Non, le dosage de la <strong>thyroglobuline</strong> n'a pas sa place dans le bilan initial d'un goitre. Il est réservé à la <strong>surveillance des cancers thyroïdiens</strong> après thyroïdectomie totale, toujours couplé à la recherche d'anticorps anti-thyroglobuline.</p>"},{"i":"4852cca3ef80","n":241,"o":"241-6","u":"Examens complémentaires","t":"Connaître les examens complémentaires à réaliser en première intention en présence d’un goitre","q":"Dans quel contexte réalise-t-on le dosage des fractions libres (T4L / T3L) dans le bilan d'un goitre ?","a":"<p>Les dosages de la <strong>T4L</strong> et de la <strong>T3L</strong> sont réalisés en seconde intention, uniquement si la <strong>TSH</strong> est anormale, afin de quantifier la dysfonction thyroïdienne.</p>"},{"i":"a2f2a757e53c","n":241,"o":"241-6","u":"Examens complémentaires","t":"Connaître les examens complémentaires à réaliser en première intention en présence d’un goitre","q":"Quels sont les deux examens complémentaires de première intention à réaliser systématiquement en cas de goitre ?","a":"<p>Les deux examens complémentaires de première intention sont le <strong>dosage de la TSH</strong> et l'<strong>échographie thyroïdienne</strong>.</p>"},{"i":"d1efd567289d","n":241,"o":"241-6","u":"Examens complémentaires","t":"Connaître les examens complémentaires à réaliser en première intention en présence d’un goitre","q":"Quel est l'intérêt de l'échographie thyroïdienne en première intention devant un goitre ?","a":"<p>L'échographie thyroïdienne est particulièrement utile, surtout si le goitre est irrégulier, pour la <strong>recherche de nodules</strong> thyroïdiens.</p>"},{"i":"09bca3827e67","n":241,"o":"241-7","u":"Définition","t":"Connaître la définition d’un nodule thyroïdien","q":"Quelle est la proportion de nodules thyroïdiens bénins et malins ?","a":"<ul><li>Les nodules thyroïdiens sont <strong>bénins dans 95 %</strong> des cas.</li><li>Les nodules thyroïdiens sont <strong>cancéreux (malins) dans 5 %</strong> des cas, avec un très bon pronostic.</li></ul>"},{"i":"1b2f2fff1d63","n":241,"o":"241-7","u":"Définition","t":"Connaître la définition d’un nodule thyroïdien","q":"Un nodule thyroïdien bénin peut-il se transformer en nodule malin ?","a":"<p>Non, la <strong>transformation d'un nodule bénin en malin n'est pas possible</strong> (ou exceptionnelle). C'est pourquoi un simple suivi des nodules considérés comme bénins est justifié.</p>"},{"i":"cf6966140ab1","n":241,"o":"241-7","u":"Définition","t":"Connaître la définition d’un nodule thyroïdien","q":"Quelle est l'épidémiologie des nodules thyroïdiens ?","a":"<ul><li>On observe une <strong>prédominance féminine (3-4 F / 1 H)</strong>.</li><li>La prévalence augmente avec l'âge : <strong>4-7 %</strong> chez la femme pour un nodule palpable, et <strong>20 %</strong> à l'échographie (plus de <strong>50 %</strong> chez la femme de plus de 50 ans).</li></ul>"},{"i":"d25b5c6a9c3b","n":241,"o":"241-7","u":"Définition","t":"Connaître la définition d’un nodule thyroïdien","q":"Quelle est la définition d'un nodule thyroïdien ?","a":"<p>Un nodule thyroïdien est une <strong>hypertrophie localisée de la glande thyroïde</strong>, de forme généralement arrondie ou ovalaire.</p>"},{"i":"6376bb7eef12","n":241,"o":"241-8","u":"Diagnostic positif","t":"Connaître les deux problématiques à résoudre en présence d’un nodule thyroïdien","q":"Quel est l'examen clé pour évaluer la fonction d'un nodule thyroïdien malin ?","a":"<p>L'examen clé est la <strong>TSH</strong> (Thyroid Stimulating Hormone). En cas de TSH basse, une <strong>scintigraphie thyroïdienne</strong> peut être réalisée pour confirmer l'hyperfonctionnement du nodule.</p>"},{"i":"c71b802e5ec6","n":241,"o":"241-8","u":"Diagnostic positif","t":"Connaître les deux problématiques à résoudre en présence d’un nodule thyroïdien","q":"Quelle est la première problématique essentielle à résoudre devant un nodule thyroïdien ?","a":"<p>La première problématique est de savoir <strong>si le nodule est hyperfonctionnel</strong>, afin de dépister un risque d'hyperthyroïdie.</p>"},{"i":"e38eefa42247","n":241,"o":"241-8","u":"Diagnostic positif","t":"Connaître les deux problématiques à résoudre en présence d’un nodule thyroïdien","q":"Quelle est la deuxième problématique essentielle à poser devant un nodule thyroïdien et quel est l'examen clé associé ?","a":"<p>La deuxième problématique est de savoir <strong>si le nodule est malin</strong>, afin de ne pas passer à côté d'un cancer. L'examen pivot est l'<strong>échographie thyroïdienne avec classification EU-TIRADS</strong>, complétée si nécessaire par une <strong>cytoponction</strong> sous échographie.</p>"},{"i":"320acb6cc347","n":241,"o":"241-9","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire et de l’examen clinique permettant la découverte et l’évaluation initiale d’un nodule","q":"Quelles sont les trois principales circonstances de découverte d'un nodule thyroïdien ?","a":"<p>Les trois principales circonstances de découverte d'un nodule thyroïdien sont :</p><ul><li>La <strong>palpation cervicale</strong> (patient ou médecin) : 40-50 % des cas.</li><li>La <strong>découverte fortuite sur imagerie</strong> : 30-40 % des cas.</li><li>Une <strong>dysthyroïdie révélatrice</strong> : 15 % des cas.</li></ul>"},{"i":"59598fdf259a","n":241,"o":"241-9","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire et de l’examen clinique permettant la découverte et l’évaluation initiale d’un nodule","q":"Quels sont les signes compressifs pouvant être associés à un nodule thyroïdien volumineux ?","a":"<p>Les signes compressifs associés à un nodule thyroïdien volumineux sont :</p><ul><li>La <strong>paralysie récurrentielle</strong>.</li><li>La <strong>dysphagie</strong>.</li><li>La <strong>dyspnée</strong> (plus tardivement).</li></ul>"},{"i":"796fef7332f9","n":241,"o":"241-9","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire et de l’examen clinique permettant la découverte et l’évaluation initiale d’un nodule","q":"Quels sont les signes cliniques à la palpation cervicale pouvant orienter vers un nodule thyroïdien malin ?","a":"<p>À la palpation cervicale, les signes suspects de malignité d'un nodule thyroïdien sont :</p><ul><li>Nodule <strong>très ferme ou dur</strong>.</li><li>Nodule <strong>irrégulier</strong>.</li><li><strong>Diamètre &gt; 3-4 cm</strong>.</li><li>Augmentation de volume <strong>&gt; 20 % par an</strong>.</li><li>Présence d'une <strong>adénopathie cervicale</strong>.</li></ul>"},{"i":"a84d920569ff","n":241,"o":"241-9","u":"Diagnostic positif","t":"Connaître les éléments de l’interrogatoire et de l’examen clinique permettant la découverte et l’évaluation initiale d’un nodule","q":"Quels sont les éléments clés à rechercher à l'interrogatoire devant la découverte d'un nodule thyroïdien et suggérant une malignité ?","a":"<p>Devant la découverte d'un nodule thyroïdien, il faut rechercher à l'interrogatoire :</p><ul><li>Des symptômes d'<strong>hyperthyroïdie</strong>.</li><li>Des symptômes de <strong>cancer médullaire</strong> (<strong>flush</strong>, <strong>diarrhée motrice</strong>).</li><li>Des <strong>facteurs de risque de malignité</strong> :<ul><li>Âge <strong>&lt; 16 ans</strong>.</li><li><strong>Irradiation cervicale</strong> dans l'enfance.</li><li><strong>NEM2</strong> (Néoplasie Endocrinienne Multiple de type 2).</li><li><strong>Antécédents familiaux de cancer médullaire thyroïdien</strong>.</li></ul></li></ul>"}]};